import{_ as t,o as a,c as i,ae as s}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Five Tab Implementations","description":"","frontmatter":{"work_package_id":"WP02","title":"Five Tab Implementations","lane":"done","dependencies":["WP01"],"base_branch":"016-workspace-lane-session-ui-tabs-WP01","base_commit":"c7a4349f4a36174dfba88caf89980d043749a5c2","created_at":"2026-03-01T13:32:40.394666+00:00","subtasks":["T006","T007","T008","T009","T010","T011"],"phase":"Phase 2 - Tab Surfaces","assignee":"","agent":"claude-haiku","shell_pid":"67756","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/016-workspace-lane-session-ui-tabs/tasks/WP02-five-tab-implementations.md","filePath":"specs/016-workspace-lane-session-ui-tabs/tasks/WP02-five-tab-implementations.md"}'),o={name:"specs/016-workspace-lane-session-ui-tabs/tasks/WP02-five-tab-implementations.md"};function l(n,e,r,c,d,p){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="work-package-prompt-wp02-five-tab-implementations" tabindex="-1">Work Package Prompt: WP02 - Five Tab Implementations <a class="header-anchor" href="#work-package-prompt-wp02-five-tab-implementations" aria-label="Permalink to &quot;Work Package Prompt: WP02 - Five Tab Implementations&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Implement all five tab surfaces: terminal, agent, session, chat, and project.</li><li>Each tab binds to the active context and renders content appropriate to its purpose.</li><li>All tabs handle data source unavailability with error states rather than crashes.</li></ul><p>Success criteria:</p><ul><li>Each tab renders correctly when the active context changes.</li><li>Terminal tab displays the active terminal for the current lane/session.</li><li>All tabs show an error state when their data source is unavailable.</li><li>Tab switch latency stays under 200ms at p95.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/016-workspace-lane-session-ui-tabs/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/016-workspace-lane-session-ui-tabs/spec.md</code></li><li>Tab surface base: <code>apps/desktop/src/tabs/tab_surface.ts</code> (WP01)</li><li>Context store: <code>apps/desktop/src/tabs/context_switch.ts</code> (WP01)</li><li>Terminal registry: spec 014 (<code>apps/runtime/src/registry/</code>)</li><li>Lane/session lifecycle: specs 008, 009</li></ul><p>Constraints:</p><ul><li>No blocking data fetches during render.</li><li>All tabs must handle missing/unavailable data gracefully.</li><li>Keep files under 500 lines each.</li><li>TypeScript + Bun + ElectroBun.</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP02</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t006-implement-terminal-tab-surface" tabindex="-1">Subtask T006 - Implement terminal tab surface <a class="header-anchor" href="#subtask-t006-implement-terminal-tab-surface" aria-label="Permalink to &quot;Subtask T006 - Implement terminal tab surface&quot;">​</a></h3><ul><li>Purpose: display the active terminal for the current lane/session context.</li><li>Steps: <ol><li>Implement <code>TerminalTab</code> extending <code>TabSurface</code> in <code>apps/desktop/src/tabs/terminal_tab.ts</code>: a. <code>onContextChange(context)</code>: i. Query the terminal registry for terminals bound to the current lane/session. ii. If terminals found, display the primary terminal&#39;s renderer output. iii. If no terminals, display &quot;No terminal for this lane&quot; with option to create one. b. <code>render()</code>: render the terminal viewport (delegate to renderer adapter output). c. <code>getState()</code>: return scroll position, terminal_id. d. <code>restoreState(state)</code>: restore scroll position and terminal selection.</li><li>Integrate with terminal spawn: provide a &quot;Create Terminal&quot; action when no terminal exists.</li><li>Handle renderer switch: during active switch transaction (spec 013), show a brief loading indicator.</li><li>Implement terminal output streaming: connect to the PTY output stream for live rendering.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/tabs/terminal_tab.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: set context with active terminal, verify terminal content rendered.</li><li>Unit test: set context with no terminal, verify empty state message.</li><li>Unit test: simulate renderer switch, verify loading indicator shown.</li></ul></li><li>Parallel: Yes (independent of other tabs).</li></ul><h3 id="subtask-t007-implement-agent-tab-surface" tabindex="-1">Subtask T007 - Implement agent tab surface <a class="header-anchor" href="#subtask-t007-implement-agent-tab-surface" aria-label="Permalink to &quot;Subtask T007 - Implement agent tab surface&quot;">​</a></h3><ul><li>Purpose: display agent activity and output for the current lane/session.</li><li>Steps: <ol><li>Implement <code>AgentTab</code> extending <code>TabSurface</code> in <code>apps/desktop/src/tabs/agent_tab.ts</code>: a. <code>onContextChange(context)</code>: i. Query agent state for the current session/lane. ii. Display agent status (idle, running, error), recent actions, and output log. iii. If no agent activity, display &quot;No agent activity for this lane.&quot; b. <code>render()</code>: render agent status panel with scrollable output log. c. <code>getState()</code>: return scroll position in output log. d. <code>restoreState(state)</code>: restore scroll position.</li><li>Implement live update: subscribe to agent events on the bus for the current session.</li><li>Handle agent errors: display error details in the tab rather than propagating.</li><li>Provide action buttons: restart agent, view full log, copy output.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/tabs/agent_tab.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: set context with active agent, verify status and output rendered.</li><li>Unit test: agent error, verify error details shown in tab.</li><li>Unit test: no agent activity, verify empty state message.</li></ul></li><li>Parallel: Yes (independent of other tabs).</li></ul><h3 id="subtask-t008-implement-session-tab-surface" tabindex="-1">Subtask T008 - Implement session tab surface <a class="header-anchor" href="#subtask-t008-implement-session-tab-surface" aria-label="Permalink to &quot;Subtask T008 - Implement session tab surface&quot;">​</a></h3><ul><li>Purpose: display session metadata, lifecycle state, and diagnostics for the current session.</li><li>Steps: <ol><li>Implement <code>SessionTab</code> extending <code>TabSurface</code> in <code>apps/desktop/src/tabs/session_tab.ts</code>: a. <code>onContextChange(context)</code>: i. Query session metadata from the session registry. ii. Display: session ID, creation time, lifecycle state, harness transport mode, terminal count. iii. Display session diagnostics: transport choice, degradation reasons if applicable. b. <code>render()</code>: render session info cards with diagnostics. c. <code>getState()</code>: return expanded/collapsed section states. d. <code>restoreState(state)</code>: restore section states.</li><li>Show harness transport diagnostic: whether <code>cliproxy_harness</code> or <code>native_openai</code> is active and why.</li><li>Display session timeline: key lifecycle events in chronological order.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/tabs/session_tab.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: set context with active session, verify metadata rendered.</li><li>Unit test: session with degraded transport, verify diagnostic info shown.</li><li>Unit test: no session, verify error state.</li></ul></li><li>Parallel: Yes (independent of other tabs).</li></ul><h3 id="subtask-t009-implement-chat-tab-surface" tabindex="-1">Subtask T009 - Implement chat tab surface <a class="header-anchor" href="#subtask-t009-implement-chat-tab-surface" aria-label="Permalink to &quot;Subtask T009 - Implement chat tab surface&quot;">​</a></h3><ul><li>Purpose: display a chat interface for conversational interaction with the agent in the current lane.</li><li>Steps: <ol><li>Implement <code>ChatTab</code> extending <code>TabSurface</code> in <code>apps/desktop/src/tabs/chat_tab.ts</code>: a. <code>onContextChange(context)</code>: i. Load chat history for the current lane/session. ii. Display message list with user and agent messages. iii. If no chat history, display empty state with input prompt. b. <code>render()</code>: render chat message list + input field. c. <code>getState()</code>: return scroll position and draft input text. d. <code>restoreState(state)</code>: restore scroll position and draft text.</li><li>Implement message input: text input with send action (Enter to send, Shift+Enter for newline).</li><li>Implement live message streaming: new agent messages appear in real time.</li><li>Handle long messages with collapsible sections.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/tabs/chat_tab.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: set context with chat history, verify messages rendered.</li><li>Unit test: send message, verify it appears in the list.</li><li>Unit test: no chat history, verify empty state.</li></ul></li><li>Parallel: Yes (independent of other tabs).</li></ul><h3 id="subtask-t010-implement-project-tab-surface" tabindex="-1">Subtask T010 - Implement project tab surface <a class="header-anchor" href="#subtask-t010-implement-project-tab-surface" aria-label="Permalink to &quot;Subtask T010 - Implement project tab surface&quot;">​</a></h3><ul><li>Purpose: display project metadata and workspace information for the active context.</li><li>Steps: <ol><li>Implement <code>ProjectTab</code> extending <code>TabSurface</code> in <code>apps/desktop/src/tabs/project_tab.ts</code>: a. <code>onContextChange(context)</code>: i. Query workspace/project metadata (spec 003). ii. Display: project name, workspace path, active lanes count, recent activity. iii. Display git status summary if applicable. b. <code>render()</code>: render project info with lane overview list. c. <code>getState()</code>: return expanded/collapsed section states. d. <code>restoreState(state)</code>: restore section states.</li><li>Display lane summary: list of all lanes in the workspace with their states.</li><li>Provide quick actions: create new lane, open workspace in file manager.</li><li>Handle workspace unavailability (e.g., disconnected external drive) with error state.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/tabs/project_tab.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: set context with active workspace, verify project info rendered.</li><li>Unit test: workspace unavailable, verify error state.</li><li>Unit test: verify lane summary shows correct lane states.</li></ul></li><li>Parallel: Yes (independent of other tabs).</li></ul><h3 id="subtask-t011-add-unit-tests-for-all-tab-surfaces" tabindex="-1">Subtask T011 - Add unit tests for all tab surfaces <a class="header-anchor" href="#subtask-t011-add-unit-tests-for-all-tab-surfaces" aria-label="Permalink to &quot;Subtask T011 - Add unit tests for all tab surfaces&quot;">​</a></h3><ul><li>Purpose: lock tab behavior and verify context binding correctness.</li><li>Steps: <ol><li>Create <code>apps/desktop/tests/unit/tabs/terminal_tab.test.ts</code>: test context binding, empty state, renderer switch handling.</li><li>Create <code>apps/desktop/tests/unit/tabs/agent_tab.test.ts</code>: test context binding, error display, empty state.</li><li>Create <code>apps/desktop/tests/unit/tabs/session_tab.test.ts</code>: test context binding, diagnostics rendering.</li><li>Create <code>apps/desktop/tests/unit/tabs/chat_tab.test.ts</code>: test context binding, message rendering, input handling.</li><li>Create <code>apps/desktop/tests/unit/tabs/project_tab.test.ts</code>: test context binding, workspace info, error state.</li><li>Each test file should verify: a. Tab updates correctly on context change. b. Tab displays error state when data source is unavailable. c. Tab state serialization/restoration works correctly.</li><li>Aim for &gt;=85% line coverage across all tab modules.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/tests/unit/tabs/terminal_tab.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/tests/unit/tabs/agent_tab.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/tests/unit/tabs/session_tab.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/tests/unit/tabs/chat_tab.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/tests/unit/tabs/project_tab.test.ts</code></li></ul></li><li>Parallel: Yes (after T006-T010 are implemented).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Unit tests with Vitest using mock context stores and data sources.</li><li>Each tab tested for context binding, error handling, and state persistence.</li><li>Aim for &gt;=85% line coverage.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: tab content loading blocks UI.</li><li>Mitigation: async data fetching with loading indicators.</li><li>Risk: data source failure crashes tab.</li><li>Mitigation: error boundary in base tab surface catches all render errors.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm each tab correctly subscribes to context changes.</li><li>Confirm error states are user-friendly and actionable.</li><li>Confirm state serialization captures all meaningful per-tab state.</li><li>Confirm no tab blocks the main UI thread during data loading.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z -- system -- lane=planned -- Prompt created.</li><li>2026-03-01T13:32:40Z – claude-haiku – shell_pid=67756 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:35:26Z – claude-haiku – shell_pid=67756 – lane=done – Implemented WP02</li></ul>',32)])])}const b=t(o,[["render",l]]);export{h as __pageData,b as default};
